def gpos_p(gene):
    pos=[[gene[i] for i in range(o,len(gene)-2,3)] for o in range(3)]
    tot=sum(len(p) for p in pos); gc=sum(p.count('G')+p.count('C') for p in pos)
    p=gc/tot; G=0
    for pp in pos:
        obs=[pp.count('G')+pp.count('C'), len(pp)-pp.count('G')-pp.count('C')]
        exp=[len(pp)*p, len(pp)*(1-p)]
        for o,e in zip(obs,exp):
            if o>0: G+=2*o*math.log(o/e)
    return [(pos[k].count('G')+pos[k].count('C'))/len(pos[k])*100 for k in range(3)], math.exp(-G/2)
